  expect(yield* Ref.get(resources)).toBe(0);
}));

it.effect.each(["startupDefect", "operationDefect"] as const)("contains private defects during %s", (mode) => Effect.gen(function* () {
  const resources = yield* Ref.make(0);
  const started = yield* Deferred.make<boolean>();
  const release = yield* Deferred.make<boolean>();
  const client = makeClientWithLayer(fixtureLayer(mode, resources, started, release), AuPay2025_26Module);
  const result = yield* Effect.promise(() => client.calculations.safe.calculate(AuPayTakeHomeCalculation, facts));
