+    Effect.flatMap(HttpClientResponse.filterStatusOk),
+    Effect.flatMap(HttpIncomingMessage.schemaBodyJson(CalculatorCatalogResponse)),
+    Effect.timeout("5 seconds"),
+    Effect.mapError(() => new ApiSmokeRouteError({ route: "catalog", reason: "request-or-response" })),
+    Effect.flatMap(catalog => Array.findFirst(catalog.calculators,
