  Effect.gen(function* () {
    const started = yield* Deferred.make<void>();
    const released = yield* Deferred.make<void>();
    const pending = Deferred.succeed(started, undefined).pipe(
      Effect.andThen(Effect.never),
      Effect.ensuring(Deferred.succeed(released, undefined))
    );
    const transport = HttpClient.make((request) =>
      phase === "headers"
        ? pending
        : Effect.succeed(HttpServerResponse.toClientResponse(
            HttpServerResponse.stream(Stream.fromEffect(pending), { contentType: "application/json" }),
            { request }
          ))
    );
    yield* Effect.gen(function* () {
      const client = yield* TaxKitRpcClient;
      const call = yield* client.calculate(CalculationRequest).pipe(Effect.forkScoped);
      yield* Deferred.await(started);
      yield* TestClock.adjust("5 seconds");
      const error = yield* Fiber.join(call).pipe(Effect.flip);
      expect(Schema.is(CalculatorRpcDeadlineExceeded)(error)).toBe(true);
      yield* Deferred.await(released);
    }).pipe(Effect.provide(TaxKitRpcClientLive(origin).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)))));
  })
);

it.effect("an earlier caller interruption closes a stalled body and remains interruption", () =>
  Effect.gen(function* () {
    const started = yield* Deferred.make<void>();
    const released = yield* Deferred.make<void>();
    const body = Stream.fromEffect(Deferred.succeed(started, undefined).pipe(
      Effect.andThen(Effect.never),
      Effect.ensuring(Deferred.succeed(released, undefined))
    ));
    const transport = HttpClient.make((request) => Effect.succeed(HttpServerResponse.toClientResponse(
      HttpServerResponse.stream(body, { contentType: "application/json" }), { request }
    )));
    yield* Effect.gen(function* () {
      const client = yield* TaxKitRpcClient;
      const call = yield* client.calculate(CalculationRequest).pipe(Effect.forkScoped);
      yield* Deferred.await(started);
      yield* Fiber.interrupt(call);
      const exit = yield* Fiber.await(call);
      expect(Exit.isFailure(exit)).toBe(true);
      if (Exit.isFailure(exit)) {
        expect(Cause.hasInterrupts(exit.cause)).toBe(true);
        expect(Cause.hasFails(exit.cause)).toBe(false);
      }
      yield* Deferred.await(released);
    }).pipe(Effect.provide(TaxKitRpcClientLive(origin).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)))));
  })
);

it.effect("closing the caller's scope interrupts pending native client work", () =>
  Effect.gen(function* () {
    const started = yield* Deferred.make<void>();
    const released = yield* Deferred.make<void>();
    const transport = HttpClient.make(() => Deferred.succeed(started, undefined).pipe(
      Effect.andThen(Effect.never),
      Effect.ensuring(Deferred.succeed(released, undefined))
    ));
    yield* Effect.gen(function* () {
      const client = yield* TaxKitRpcClient;
      yield* client.calculate(CalculationRequest).pipe(Effect.forkScoped);
      yield* Deferred.await(started);
    }).pipe(Effect.provide(TaxKitRpcClientLive(origin).pipe(Layer.provide(Layer.succeed(HttpClient.HttpClient, transport)))), Effect.scoped);
    yield* Deferred.await(released);
  })
);

it.effect("applies credential and redirect policy when the HTTP operation runs", () =>
  Effect.gen(function* () {
    const reached = yield* Deferred.make<Readonly<{ credentials: RequestCredentials | undefined; redirect: RequestRedirect | undefined }>>();
    const transport = HttpClient.make(() => Effect.gen(function* () {
      const policy = yield* FetchHttpClient.RequestInit;
      yield* Deferred.succeed(reached, { credentials: policy.credentials, redirect: policy.redirect });
      return yield* Effect.never;
    }));
    yield* Effect.gen(function* () {
      const client = yield* TaxKitRpcClient;
      const call = yield* client.calculate(CalculationRequest).pipe(Effect.forkScoped);
      expect(yield* Deferred.await(reached)).toEqual({ credentials: "omit", redirect: "error" });
