Path('apps/web/src/lib/config.server.ts').write_text('''import "@tanstack/react-start/server-only";
import type { fromCloudflareFetcher } from "alchemy/Cloudflare/Fetcher";
import { Config, Effect, Predicate, Schema } from "effect";

import { TaxKitWebConfigError } from "./config";
import { WebsiteHostOrigins } from "./schemas";

// This is the native SDK capability boundary. Preserve the original Fetcher
// object (and method receiver); a Struct would copy its methods off the binding.
const PrivateApiBinding = Schema.declare<Parameters<typeof fromCloudflareFetcher>[0]>(
  (value) => Predicate.isObject(value) &&
    Predicate.hasProperty(value, "fetch") && Predicate.isFunction(value.fetch) &&
    Predicate.hasProperty(value, "connect") && Predicate.isFunction(value.connect)
);
export const TaxKitWebServerConfig = Config.all({
  apiOrigin: Config.schema(WebsiteHostOrigins.fields.apiOrigin, "API_PUBLIC_ORIGIN"),
  binding: Config.schema(PrivateApiBinding, "TAXKIT_API"),
  websiteOrigin: Config.schema(WebsiteHostOrigins.fields.websiteOrigin, "WEBSITE_PUBLIC_ORIGIN"),
}).pipe(
  Effect.mapError(() => new TaxKitWebConfigError({
    message: "TaxKit web settings are missing or invalid.",
    operation: "settings",
    runtime: "server",
  }))
);
''')
Path('apps/web/src/lib/service.server.ts').write_text('''import type { CalculatorRpcClientError } from "@taxkit/api-rpc/errors";
import type { CalculatorRunResponse, CalculatorRunServiceRequest } from "@taxkit/api-rpc/schemas";
import { Context } from "effect";
import type { Effect } from "effect";

import type { TaxKitWebConfigError } from "./config";
import type { WebsitePublicSettings } from "./schemas";

export interface WebsiteServerApplicationContract {
  readonly settings: Effect.Effect<WebsitePublicSettings, TaxKitWebConfigError>;
  readonly calculate: (request: CalculatorRunServiceRequest) => Effect.Effect<
    CalculatorRunResponse, CalculatorRpcClientError | TaxKitWebConfigError
  >;
}
