import type { WebsitePublicSettings } from "./schemas";

// These are descriptions of work. React's registry owns client acquisition,
// execution and release; no module creates or runs a browser ManagedRuntime.
export const publicSettingsAtom = Atom.make(Option.none<WebsitePublicSettings>());
export const calculatorRuntime = Atom.runtime((get) => Option.match(get(publicSettingsAtom), {
  onNone: () => Layer.fail(new TaxKitWebConfigError({ message: "TaxKit web settings are missing or invalid.", operation: "settings", runtime: "client" })),
  onSome: (settings) => TaxKitRpcClientLive(settings.apiOrigin).pipe(Layer.provide(FetchHttpClient.layer)),
}));
export const calculateAtom = calculatorRuntime.fn<CalculatorRunServiceRequest>()((request) => TaxKitRpcClient.pipe(Effect.flatMap((client) => client.calculate(request))));
export const takeHomeFormAtom = Atom.make(initialTakeHomeForm);
export const showCalculationAtom = Atom.make(false);
export const formErrorAtom = Atom.make(Option.none<string>());
export const editTakeHomeAtom = Atom.fnSync<TakeHomeForm>()((form, get) => {
  get.set(calculateAtom, Atom.Interrupt);
  get.set(showCalculationAtom, false);
  get.set(formErrorAtom, Option.none());
