import { createStartHandler, defaultStreamHandler } from "@tanstack/react-start/server";
import { Effect, Result, Schema } from "effect";
import { HttpServerRequest, HttpServerResponse } from "effect/http";

import { decodeTakeHomeForm, TakeHomeForm, WebsiteInputError } from "./lib/form.boundary";
import { appRuntime } from "./lib/runtime.server";
import { WebsiteSubmission, WebsiteSubmissionTransport } from "./lib/schemas";
import type { WebsiteServerRenderContext } from "./lib/schemas";
import { WebsiteServerApplication } from "./lib/service.server";

const render = createStartHandler<{ server: { requestContext: WebsiteServerRenderContext } }>(defaultStreamHandler);

export default {
  fetch: (request: Request) => {
    if (request.method !== "POST" || new URL(request.url).pathname !== "/") {
      return render(request, { context: {} });
    }
    // A standard HTML form remains usable without JavaScript. Its checked
    // request reaches the same named RPC client through the private binding.
    // Only plain, Schema-encoded form/report data reaches TanStack rendering.
    return appRuntime.runPromise(withCalculatorRequestBodyLimit(Effect.gen(function* () {
      const incoming = yield* HttpServerRequest.HttpServerRequest;
      const bounded = yield* HttpServerRequest.toWeb(incoming, { signal: request.signal });
      const data = yield* Effect.tryPromise({ try: () => bounded.formData(), catch: () => new WebsiteInputError({ message: "Enter a valid pay amount and pay period." }) });
