      const headers = new Headers(request.headers);
      headers.delete("content-length");
      headers.delete("content-type");
      const response = yield* Effect.promise(() => render(new Request(request.url, { headers, method: "GET", signal: request.signal }), { context: { submission } }));
      return HttpServerResponse.fromWeb(response);
    })).pipe(
      Effect.catchTag("WebsiteInputError", () => Effect.succeed(HttpServerResponse.empty({ status: 400 }))),
      Effect.provideService(HttpServerRequest.HttpServerRequest, HttpServerRequest.fromWeb(request)),
      Effect.scoped,
      Effect.map(HttpServerResponse.toWeb)
    ), { signal: request.signal });
  },
};
