import { Effect, Option, Result, Schema } from "effect";
import * as AsyncResult from "effect/reactivity/AsyncResult";
import * as AtomRegistry from "effect/reactivity/AtomRegistry";

import { calculateAtom, publicSettingsAtom } from "./calculator.atoms";
import { initialTakeHomeForm, takeHomeRequestFromForm } from "./form.boundary";
import { WebsitePublicSettings } from "./schemas";

describe("browser calculator acquisition", () => {
  it.effect("starts a checked request with public settings", () => Effect.gen(function* () {
    const apiOrigin = yield* Schema.decodeUnknownEffect(WebsitePublicSettings.fields.apiOrigin)("http://127.0.0.1:49999");
    const request = yield* Effect.fromResult(takeHomeRequestFromForm(initialTakeHomeForm));
    const registry = yield* Effect.acquireRelease(Effect.sync(() => AtomRegistry.make({ initialValues: [[publicSettingsAtom, Option.some(WebsitePublicSettings.make({ apiOrigin }))]] })), (value) => Effect.sync(() => value.dispose()));
    const unmount = registry.mount(calculateAtom);
    yield* Effect.addFinalizer(() => Effect.sync(unmount));
    registry.set(calculateAtom, request);
    yield* Effect.promise(() => expect.poll(() => AsyncResult.isFailure(registry.get(calculateAtom))).toBe(true));
    const result = registry.get(calculateAtom);
    if (AsyncResult.isFailure(result)) {
      const failure = yield* result.cause.pipe(Effect.failCause, Effect.result);
      expect(failure).toEqual(Result.fail({ _tag: "CalculatorRpcUnavailable" }));
    }
  }).pipe(Effect.scoped));
});
