    registry.set(submitTakeHomeAtom, undefined);
    yield* Effect.promise(() => expect.poll(() => started.mock.calls.length).toBe(1));
    registry.set(editTakeHomeAtom, { ...initialTakeHomeForm, grossDollars: "2000" });
    yield* Effect.promise(() => expect.poll(() => cancelled.mock.calls.length).toBe(1));
    expect(registry.get(calculateAtom).waiting).toBe(false);
  }).pipe(Effect.scoped));

  it.effect("leaving the rendered form interrupts work before the registry is disposed", () => Effect.gen(function* () {
    const started = vi.fn();
    const cancelled = vi.fn();
    const client = Layer.succeed(TaxKitRpcClient, TaxKitRpcClient.of({ calculate: Effect.fn("TaxKitRpcClient.calculate")(() => Effect.sync(started).pipe(Effect.andThen(Effect.never), Effect.onInterrupt(() => Effect.sync(cancelled)))) }));
    const registry = yield* Effect.acquireRelease(Effect.sync(() => AtomRegistry.make({ initialValues: [[calculatorRuntime.layer, client]] })), (value) => Effect.sync(() => value.dispose()));
    const host = yield* Effect.acquireRelease(Effect.sync(() => {
