    root.render(<RegistryContext.Provider value={registry}><p>Another page</p></RegistryContext.Provider>);
    yield* Effect.promise(() => expect.poll(() => cancelled.mock.calls.length).toBe(1));
    expect(host.textContent).toBe("Another page");
  }).pipe(Effect.scoped));

