    const called = vi.fn();
    const errors = vi.fn();
    const client = Layer.succeed(TaxKitRpcClient, TaxKitRpcClient.of({ calculate: Effect.fn("TaxKitRpcClient.calculate")(() => Effect.sync(called).pipe(Effect.andThen(Effect.fail(new CalculatorRpcUnavailable())))) }));
    const submission = yield* Schema.encodeEffect(WebsiteSubmissionTransport)(WebsiteSubmission.make({ form: initialTakeHomeForm, result: Result.fail(new CalculatorRpcUnavailable()) }));
    const registry = yield* Effect.acquireRelease(Effect.sync(() => AtomRegistry.make({ initialValues: [[calculatorRuntime.layer, client]] })), (value) => Effect.sync(() => value.dispose()));
