      API_PUBLIC_ORIGIN: { type: "json" as const, value: apiOrigin },
      WEBSITE_PUBLIC_ORIGIN: { type: "json" as const, value: websiteOrigin },
      WORKER_URL: { type: "json" as const, value: apiOrigin },
    }, manifest: { mainModule: "worker.js", modules: apiModules, modulesRoot: apiRoot }, name } });
    const publicApi = yield* Effect.acquireRelease(Effect.sync(() => new Miniflare({ cf: false, handleStructuredLogs: (log) => { Queue.offerUnsafe(logs, log); }, handleUncaughtError: (error) => { Queue.offerUnsafe(exceptions, error.message); }, host: "127.0.0.1", port: 4197, workers: [apiWorker("taxkit-public-api")] })), (host) => Effect.promise(() => host.dispose()));
    const website = yield* Effect.acquireRelease(Effect.sync(() => new Miniflare({ cf: false, handleStructuredLogs: (log) => { Queue.offerUnsafe(logs, log); }, handleUncaughtError: (error) => { Queue.offerUnsafe(exceptions, error.message); }, host: "127.0.0.1", port: 4196, workers: [{ config: { assets: { directory: path.join(root, "apps/web/dist/client"), hasUserWorker: true, runWorkerFirst: false }, compatibilityDate: "2026-10-04", compatibilityFlags: ["nodejs_compat"], env: {
      API_PUBLIC_ORIGIN: { type: "json", value: apiOrigin },
      TAXKIT_API: { type: "worker", worker: "taxkit-private-api" },
      WEBSITE_PUBLIC_ORIGIN: { type: "json", value: websiteOrigin },
    }, manifest: { mainModule: "server.js", modules: websiteModules, modulesRoot: websiteRoot }, name: "taxkit-website" } }, apiWorker("taxkit-private-api")] })), (host) => Effect.promise(() => host.dispose()));
    yield* Effect.promise(() => publicApi.ready);
    yield* Effect.promise(() => website.ready);
    const initial = yield* Effect.promise(() => website.dispatchFetch(`${websiteOrigin}/`));
    const initialHtml = yield* Effect.promise(() => initial.text());
    expect(initial.status).toBe(200);
    expect(initialHtml).toContain("Pay before tax");
    expect(initialHtml).not.toContain("Take-home pay:");
    const server = yield* Effect.promise(() => website.dispatchFetch(`${websiteOrigin}/`, { body: form, headers: { "content-type": "application/x-www-form-urlencoded" }, method: "POST" }));
    expect(server.status).toBe(200);
    const serverHtml = yield* Effect.promise(() => server.text());
    expect(serverHtml).toContain("$1,301.00");
    // A second request after the isolate has been idle catches native receive
