    yield* Effect.sleep("750 millis");
    const repeated = yield* Effect.promise(() => website.dispatchFetch(`${websiteOrigin}/`, { body: form, headers: { "content-type": "application/x-www-form-urlencoded" }, method: "POST" }));
    expect(repeated.status).toBe(200);
    expect(yield* Effect.promise(() => repeated.text())).toContain("$1,301.00");
    const browser = yield* Effect.acquireRelease(Effect.promise(() => chromium.launch({ headless: true })), (value) => Effect.promise(() => value.close()));
    const context = yield* Effect.acquireRelease(Effect.promise(() => browser.newContext()), (value) => Effect.promise(() => value.close()));
    const page = yield* Effect.promise(() => context.newPage());
    const calls = yield* Queue.make<{ readonly method: string; readonly url: string; readonly headers: Readonly<Record<string, string>> }>();
    page.on("request", (request) => { if (new URL(request.url()).pathname.startsWith("/rpc")) { Queue.offerUnsafe(calls, { headers: request.headers(), method: request.method(), url: request.url() }); } });
