    yield* Effect.promise(() => plainPage.getByRole("button", { name: "Calculate", exact: true }).click());
    yield* Effect.promise(() => plainPage.getByText("$1,301.00", { exact: true }).waitFor());
    expect(yield* Queue.takeAll(exceptions)).toEqual([]);
    const logText = yield* Schema.encodeEffect(Json)(yield* Queue.takeAll(logs));
    expect(logText).not.toContain("1654");
    expect(logText).not.toContain("130100");
  }).pipe(Effect.scoped, Effect.provide(NodeServices.layer)));
});
